    document.addEventListener('mouseout',function(e){ if(cur&&hit(e)===cur) hide(); });
    document.addEventListener('focusin',function(e){ var el=hit(e); if(el) show(el); });
    document.addEventListener('focusout',function(){ if(cur) hide(); });
