  var PRV={on:lsGet(LS_PRIV)!=='0',shown:{}}, PRV_V={}, PRV_K={};
  /* 掩码策略：h/t ＝ 首尾各保留多少个「有效字符」（字母数字，分隔符不计）。
     分隔符一律原样保留 ⇒ 掩码串与明文等长，切换时列宽零位移。
     有效字符不足 h+t 时整串全掩：短值一旦"保留"就等于没掩。 */
  var PRV_KEEP={tel:{h:3,t:4},id:{h:4,t:4},mac:{h:4,t:2},ip:{h:6,t:0}};
  function prvMask(kind,v){
    var s=String(v==null?'':v), k=PRV_KEEP[kind]||PRV_KEEP.id, idx=[], i;
    for(i=0;i<s.length;i++) if(/[0-9A-Za-z]/.test(s.charAt(i))) idx.push(i);
    if(!idx.length) return s;                       /* '--' / '未配置' 之类原样返回 */
    if(idx.length<=k.h+k.t) return s.replace(/[0-9A-Za-z]/g,'•');
    var out=s.split('');
    for(i=k.h;i<idx.length-k.t;i++) out[idx[i]]='•';
    return out.join('');
  }
  var EYE_ON='<svg class="ic-on" viewBox="0 0 24 24" aria-hidden="true">'+
    '<path d="M2 12s3.8-6.6 10-6.6S22 12 22 12s-3.8 6.6-10 6.6S2 12 2 12z"/><circle cx="12" cy="12" r="2.9"/></svg>';
  var EYE_OFF='<svg class="ic-off" viewBox="0 0 24 24" aria-hidden="true">'+
    '<path d="M4.2 7.4C2.8 9 2 12 2 12s3.8 6.6 10 6.6c2.1 0 3.9-.7 5.4-1.6"/>'+
    '<path d="M9.6 5.7A11 11 0 0 1 12 5.4c6.2 0 10 6.6 10 6.6a19 19 0 0 1-2.7 3.4"/>'+
    '<path d="M4 4l16 16"/><circle cx="12" cy="12" r="2.6"/></svg>';
  function eyeBtn(key,hid){
    var lb=hid?'显示明文':'隐藏明文';
    return '<button type="button" class="a2-eye" data-a="pvtoggle" data-pvk="'+esc(key)+'"'+
      ' aria-pressed="'+(hid?'false':'true')+'" aria-label="'+lb+'" title="'+lb+'">'+
      EYE_ON+EYE_OFF+'</button>';
  }
  /* 渲染入口：kv / rows 的值位都走这里。key 是同域内稳定唯一的标识
     （'dev:imei' 这种），用于跨重渲染恢复单点状态，也是点击时取明文的唯一凭据。 */
  function prvVal(key,kind,v){
    var plain=String(v==null?'':v);
    if(!plain||!/[0-9A-Za-z]/.test(plain)) return esc(plain);   /* '--' / 中文占位：无可掩之物 */
    PRV_V[key]=plain; PRV_K[key]=kind;
    if(!PRV.on) return esc(plain);                             /* 总开关关闭：明文，且不出眼睛 */
    var hid=!PRV.shown[key];
    return '<span class="a2-prv'+(hid?'':' is-on')+'">'+
      '<span class="a2-pvt">'+esc(hid?prvMask(kind,plain):plain)+'</span>'+
      eyeBtn(key,hid)+'</span>';
  }
  function prvPaint(btn,key){
    var box=btn.parentNode, pt=box&&box.querySelector?box.querySelector('.a2-pvt'):null;
    var plain=PRV_V[key]==null?'':PRV_V[key], hid=!PRV.shown[key], lb=hid?'显示明文':'隐藏明文';
    if(pt) pt.textContent=hid?prvMask(PRV_K[key],plain):plain;
    if(box&&box.classList) box.classList.toggle('is-on',!hid);
    btn.setAttribute('aria-pressed',hid?'false':'true');
    btn.setAttribute('aria-label',lb); btn.setAttribute('title',lb);
  }
  function prvToggle(btn){
    var key=btn.getAttribute('data-pvk');
    if(!key||!PRV.on||PRV_V[key]==null) return;
    PRV.shown[key]=!PRV.shown[key];
    prvPaint(btn,key);
    /* 就地改文本后作废宿主槽位的 morph 缓存：否则下次 patchSlot 拿着「按新状态生成」的 HTML
       与旧串比对，会再写一遍同样的文本（结果没错，但白跑一轮 DOM 操作）。 */
    var sl=btn.closest&&btn.closest('[data-slot]'); if(sl) sl.__a2h=null;
  }
  /* 终端标识卡的「显示明文 / 隐藏明文」整卡开关：4 个眼睛逐个点太碎，
     且掩码串在窄列里会被 ellipsis 裁掉，一键全显才是可用的查看路径（v2.4.20 用户反馈）。 */
  var PRV_CARD_KEYS=['dev:imei','dev:iccid','dev:imsi','dev:num'];
  function prvCardShown(){
    if(!PRV.on) return false;
    for(var i=0;i<PRV_CARD_KEYS.length;i++) if(!PRV.shown[PRV_CARD_KEYS[i]]) return false;
    return true;
  }
  function prvShowAll(on,btn){
    if(!PRV.on){ toast('隐私保护总开关已关闭，当前全部明文','is-ok'); return; }
    $$('.a2-view.a2-on .a2-prv').forEach(function(box){
      var eb=box.querySelector?box.querySelector('.a2-eye'):null; if(!eb) return;
      var key=eb.getAttribute('data-pvk');
      if(PRV_V[key]==null) return;
      PRV.shown[key]=on;
      prvPaint(eb,key);
      var sl=eb.closest&&eb.closest('[data-slot]'); if(sl) sl.__a2h=null;
    });
    if(btn&&btn.textContent!=null){
      btn.textContent=on?'隐藏明文':'显示明文';
      btn.setAttribute('data-cmd',on?'0':'1');
    }
    toast(on?'已显示明文（仅本次会话有效）':'已恢复掩码');
  }
  function prvSync(){
    $$('[data-a="prvtgl"]').forEach(function(b){
      if(b.classList) b.classList.toggle('is-on',PRV.on);
      b.setAttribute('aria-checked',PRV.on?'true':'false');
    });
    /* 设置域行内状态文案（账户与安全 · 隐私保护行）：该 span 带 aria-live，切换即被读屏播报 */
    $$('[data-xst="prv"]').forEach(function(n){
      n.className='a2-sval '+(PRV.on?'is-on':'is-off');
      n.textContent=PRV.on?'已开启':'已关闭';
    });
  }
  function prvMaster(){
    PRV.on=!PRV.on;
    PRV.shown={};                       /* 关：清掉单点显示；开：统一回掩码，不留残留 */
    lsSet(LS_PRIV,PRV.on?'1':'0');
    prvSync();
    /* 其它域可能在后台已渲染过、槽位里还挂着旧的掩码/明文串：
       全部作废缓存，切回该域时 show() 重渲染即可按新状态出图。 */
    $$('[data-slot]').forEach(function(n){ n.__a2h=null; });
    toast(PRV.on?'隐私保护已开启，敏感标识恢复掩码':'隐私保护已关闭，敏感标识以明文显示',
      PRV.on?'is-ok':'is-warn');
  }
  function bar(p,txt){ p=Math.max(0,Math.min(100,num(p)));
    var cls=p>=90?' is-bad':(p>=75?' is-warn':'');
    return '<div class="a2-bar'+cls+'"><i style="width:'+p.toFixed(1)+'%"></i></div>'+
      (txt?'<div class="a2-sub" style="margin-top:var(--a2-sp-2)">'+txt+'</div>':''); }
  function rows(list){ if(!list||!list.length) return '<div class="a2-note">暂无数据</div>';
    return list.map(function(r){
      /* act：行内操作按钮 HTML（商店「安装」用，调用方自行转义属性） */
      return '<div class="a2-item"><div class="a2-t"><span>'+r.t+'</span>'+
        (r.act||'')+
        (r.d?'<span class="a2-d">'+esc(r.d)+'</span>':'')+'</div>'+
        (r.b?'<div class="a2-b">'+r.b+'</div>':'')+'</div>'; }).join(''); }
  /* keys（可选）：每行的稳定标识，配合增量重绘做「按键复用行」：
     列表新增条目时只插入一行，而不是把后面每行的内容都改写一遍。 */
  function table(head,body,cls,keys){ return '<div class="a2-scroll'+(cls?' '+cls:'')+'"><table class="a2-tbl"><thead><tr>'+
    head.map(function(h){ return '<th>'+esc(h)+'</th>'; }).join('')+'</tr></thead><tbody>'+
    (body.length?body.map(function(r,i){ return '<tr'+((keys&&keys[i]!=null)?' data-k="'+esc(String(keys[i]))+'"':'')+'>'+
      r.map(function(c){ return '<td>'+c+'</td>'; }).join('')+'</tr>'; }).join('')
      :'<tr><td colspan="'+head.length+'">暂无数据</td></tr>')+'</tbody></table></div>'; }
  /* ---- 三个构造器的 opts 重载（S6）----
     旧形态全兼容，存量调用一处未改（201 处 btn / 117 处 card / 54 处 kv）。新代码写 opts：
       btn('清理选中项','memgc','',{sure:'将停止勾选的服务…',danger:true,dis:false,svc:'adg'})
       card('标题',inner,{tag:'写',wide:'all',goto:'system',hact:h})
       kv(obj,{cols:3,line:true,span:['IPv6 地址']})
     🔴 判 opts 的哨兵是「该位置是对象且非 null」：btn 第 4 参 tip 本是字符串、card 第 3 参 tag
        本是字符串或空、kv 第 2 参本是字符串或布尔，三者都不可能是真对象，故不会误判。
     🔴 位置形态的问题是布尔夹在中间：btn 的 danger(5)/dis(6) 之间隔着 tip(4)，多写一个逗号
        就静默错位成「按钮文案变提示语」，201 处调用全靠数逗号读。opts 形态没有这个风险。 */
  function btn(label,a,cmd,tip,danger,dis,svc){
    var tailCls='', priCls='';
    if(tip&&typeof tip==='object'){
      var o=tip;
      tip=o.sure||o.tip||''; danger=!!o.danger; dis=!!o.dis; svc=o.svc||'';
      if(o.cmd!=null) cmd=o.cmd;
      /* o.tail=危险按钮并入主行右端；o.pri=本屏主操作（实心），每组最多一个。 */
      if(o.tail) tailCls=' is-tail-btn';
      if(o.pri) priCls=' is-primary';
    }
    return '<button class="a2-btn'+(danger?' is-danger':'')+tailCls+priCls+'" data-a="'+a+'"'+
      (cmd?' data-cmd="'+esc(cmd)+'"':'')+
      (svc?' data-svc="'+esc(svc)+'"':'')+
      (tip?' data-sure="1" data-tip="'+esc(tip)+'"':'')+
      (dis?' disabled':'')+'>'+esc(label)+'</button>'; }
  function field(label,inner){ return '<div class="a2-field"><label>'+esc(label)+'</label>'+inner+'</div>'; }
  function badge(on,t){ return on?'<span class="a2-badge">'+esc(t||'开')+'</span>':
    '<span class="a2-badge is-off">'+esc(t||'关')+'</span>'; }
  /* 健康总览色块（云盘守护状态）：state=ok|warn|bad|off|na，图标用内置 SVG
     na = 未安装（区别于 off = 已装未运行），虚线边框 + 品牌色，避免和「停止」混淆 */
  function hbIcon(state){
    if(state==='ok') return '<svg viewBox="0 0 24 24"><path d="M5 12.5l4.5 4.5L19 7"/></svg>';
    if(state==='bad') return '<svg viewBox="0 0 24 24"><path d="M12 7v6"/><path d="M12 17h.01"/></svg>';
    if(state==='warn') return '<svg viewBox="0 0 24 24"><path d="M12 3l9 16H3z"/><path d="M12 10v4"/><path d="M12 17h.01"/></svg>';
    if(state==='na') return '<svg viewBox="0 0 24 24"><path d="M12 5v9"/><path d="M12 18h.01"/><path d="M4 12a8 8 0 0 1 13-6"/><path d="M20 12a8 8 0 0 1-13 6"/></svg>';
    return '<svg viewBox="0 0 24 24"><path d="M12 4v8"/><path d="M7 7a7 7 0 1 0 10 0"/></svg>';
  }
  function svcHealthBanner(state,title,sub){
    state=state||'off';
    return '<div class="a2-hb is-'+state+'">'
      +'<span class="a2-hb-ic">'+hbIcon(state)+'</span>'
      +'<div class="a2-hb-b"><div class="a2-hb-t">'+esc(title||'--')+'</div>'
      +(sub?'<div class="a2-hb-s">'+esc(sub)+'</div>':'')+'</div></div>';
  }
  function skelHb(){ return svcHealthBanner('off','读取中…','正在连接设备获取守护与挂载状态'); }

  /* ---- 通用件 G1：数据时间戳（十域优化第一批）----
     卡片渲染末尾统一挂一行「更新于 HH:MM:SS · 每 Ns」，让用户一眼看出数据新旧。
     历史问题：signal/network/device 等六域无自动刷新也无时间戳，
     用户分不清屏幕上是实时值还是上次打开时的旧值。 */
  function stamp(sec){
    return '<div class="a2-stamp">'+stampTxt(Date.now(),sec)+'</div>';
  }
  /* 数据新鲜度文案的唯一出处：卡片底部 stamp() 与服务页顶部 sv2live 共用一份。
     原来服务页写「实时 12:00:00 · 每 3 秒刷新」，卡片写「更新于 12:00:00 · 每 3 秒自动刷新」，
     同一个概念两套说法、两个时间口径（一个是数据时刻，一个是当前时刻），读起来像两件事。 */
  function stampTxt(t,sec){
    return '更新于 '+liveClock(t||Date.now())+(sec?' · 每 '+sec+' 秒自动刷新':'');
  }
  /* 实时域结论卡的新鲜度条（P2-1 定稿的标准）。
     🔴 实时域（overview / traffic / audit / exp）的「当前值」卡必须带这一行，其余域可省。
     与 stamp() 的区别：stamp() 把时刻烧进 HTML，只有整卡重绘才会变；实时卡的数值靠
     patchSlot 逐项刷新、卡骨架不动，烧进去的时刻会永远停在进页那一刻，比不显示更误导。
     所以这里只放空壳 + 刷新周期，文本由 LIVE 中枢在每次取数完成后统一重绘。 */
  function liveStampNode(){
    return '<div class="a2-stamp" data-lstamp="'+num(LIVE_IV)+'"></div>';
  }
  function paintLStamps(){
    var n=$$('.a2-stamp[data-lstamp]'); if(!n.length) return;
    var t=LIVE.last||Date.now(), i, s;
    for(i=0;i<n.length;i++){
      s=num(n[i].getAttribute('data-lstamp'));
      n[i].textContent=stampTxt(t,s);
    }
  }
  /* ---- 通用件 G2：长表「加载更多」（十域优化第一批）----
     替代 slice(0,N) 硬截断：先展示 step 条，点「加载更多」每次加 step，
     底部显示「已显示 n / 共 N 条」。MORE_N 记每张表的当前展示量（域内状态，
     切走再回来保留）；MORE_RENDER 注册该表的重渲染函数，点击后由分发器调用。 */
  var MORE_N={}, MORE_RENDER={}, MORE_STEP={};
  function moreReset(key){ delete MORE_N[key]; }
  function moreTail(key,total,step){
    step=step||20; total=num(total);
    MORE_STEP[key]=step;   /* 步长随表登记：分发器只知道 key，这里替它记住该表一次加多少 */
    var shown=Math.min(MORE_N[key]||step,total);
    var h='<div class="a2-more"><span class="a2-sub">已显示 '+shown+' / '+total+' 条</span>';
    if(shown<total) h+='<button type="button" class="a2-btn" data-a="a2more" data-mk="'+esc(key)+'">加载更多</button>';
    return h+'</div>';
  }
  /* 每次追加该表自己的步长。早先这里写死 20，与 audct(60)/clients(25) 的步长不一致，
     点「加载更多」会把 60 条缩成 40 条（越点越少），故改为读 MORE_STEP。 */
  function morePage(key){
    var step=MORE_STEP[key]||20;
    MORE_N[key]=(MORE_N[key]||step)+step;
    var f=MORE_RENDER[key]; if(f) f();
  }

  var NET_TYPE={0:'未知',1:'GPRS',2:'EDGE',3:'UMTS',4:'HSDPA',5:'HSUPA',6:'HSPA',
    7:'TD-SCDMA',8:'HSPA+',9:'EVDO',10:'1xRTT',11:'LTE',12:'eHRPD',
    20:'5G NR',21:'5G NSA',22:'5G SA',23:'LTE / 5G NSA'};
  function netName(t){ t=String(t==null?'':t);
    if(!t) return '--';
    if(/[^\d]/.test(t)) return t;
    return NET_TYPE[num(t)]||t; }

  /* ============ 视图 ============ */
  /* ---- 域登记表（S3）：一个域的身份只在这里写一次 ----
     以前新增一个域要改 9 处（VIEWS / NAV_GROUPS / ICONS / RENDER / LIVE_VIEWS，外加
     show / refresh / perform / RETRY_FN 里的特判），漏一处就是「导航里有、点进去空白」
     或「实时角标永远不亮」这类半截状态。现在必改两处：本表加一条、写对应视图函数，
     VIEWS / ICONS / LIVE_VIEWS / RENDER 四个表全部从本表派生。
     🔴 r 直接写函数名，靠函数声明提升：viewXxx 都定义在文件后半段，但这一句求值时
        已经提升到 IIFE 顶部，引用安全（别在表里写 function(){}，否则每次求值都新建函数）。
     🔴 本表顺序 = VIEWS 顺序：视图容器创建顺序、全量搜索索引、版本行里的域计数都吃它，
        改顺序等于改界面，别顺手重排。
     🔴 live=1 表示该域参与实时轮询角标（原 LIVE_VIEWS 的四个键）。
     🔴 show() / refresh() 里仍有针对个别域的行为特判（system 的 LOG_FP 复位、services 的
        hub 重置、overview 的首屏刷新等），那是**行为差异**不是登记遗漏：普通新域不需要动它们。 */
  var DOMAINS=[
    {id:'overview',n:'概览',live:1,r:viewOverview,
      ic:'<rect x="2" y="2" width="5" height="5" rx="1.2"/><rect x="9" y="2" width="5" height="5" rx="1.2"/><rect x="2" y="9" width="5" height="5" rx="1.2"/><rect x="9" y="9" width="5" height="5" rx="1.2"/>'},
    {id:'signal',n:'信号',r:viewSignal,
      ic:'<rect x="1.8" y="10.8" width="2.4" height="3.2" rx="1"/><rect x="5.6" y="8.2" width="2.4" height="5.8" rx="1"/><rect x="9.4" y="5.6" width="2.4" height="8.4" rx="1"/><rect x="13.2" y="2.4" width="2.4" height="11.6" rx="1"/>'},
    {id:'exp',n:'体验',live:1,r:viewExp,
      ic:'<path d="M2.4 11.4a5.6 5.6 0 0 1 11.2 0"/><path d="M8 11.4l3-3.8"/>'},
    {id:'network',n:'网络',r:viewNetwork,
      ic:'<circle cx="8" cy="8" r="6"/><ellipse cx="8" cy="8" rx="2.7" ry="6"/><path d="M2.3 6.1h11.4M2.3 9.9h11.4"/>'},
    {id:'traffic',n:'流量',live:1,r:viewTraffic,
      ic:'<path d="M5.2 13.4V3.2"/><path d="M2.6 5.8L5.2 3.2l2.6 2.6"/><path d="M10.8 2.6v10.2"/><path d="M8.2 10.2l2.6 2.6 2.6-2.6"/>'},
    {id:'audit',n:'审计',live:1,r:viewAudit,
      ic:'<circle cx="7.2" cy="7.2" r="4.4"/><path d="M10.5 10.5L14 14"/>'},
    {id:'sms',n:'短信',r:viewSms,
      ic:'<path d="M3 2.6h10a1.4 1.4 0 0 1 1.4 1.4v5.6a1.4 1.4 0 0 1-1.4 1.4H7.2l-3.4 2.8v-2.8H3A1.4 1.4 0 0 1 1.6 9.6V4A1.4 1.4 0 0 1 3 2.6z"/>'},
    {id:'device',n:'设备',r:viewDevice,
      ic:'<rect x="4.4" y="1.8" width="7.2" height="12.4" rx="1.8"/><path d="M7 12h2"/>'},
    {id:'services',n:'服务',r:viewServices,
      ic:'<path d="M8 2l6 3.2-6 3.2-6-3.2z"/><path d="M2 9.4l6 3.2 6-3.2"/>'},
    {id:'boost',n:'加速',r:viewBoost,
      ic:'<path d="M8.6 1.6L3.6 8.9h3.7l-1 5.5 6.7-7.3H9.5z"/>'},
    {id:'system',n:'系统',r:viewSystem,
      ic:'<circle cx="8" cy="8" r="3"/><rect x="6.8" y=".9" width="2.4" height="2.6" rx="1"/><rect x="6.8" y="12.5" width="2.4" height="2.6" rx="1"/><rect x=".9" y="6.8" width="2.6" height="2.4" rx="1"/><rect x="12.5" y="6.8" width="2.6" height="2.4" rx="1"/>'},
    {id:'plugins',n:'插件',r:viewPlugins,
      ic:'<path d="M2.6 2.6h3.6a1.7 1.7 0 1 1 3.4 0h3.8v3.6a1.7 1.7 0 1 0 0 3.4v3.8H9.6a1.7 1.7 0 1 1-3.4 0H2.6z"/>'},
    {id:'settings',n:'设置',r:viewSettings,
      ic:'<rect x="1.8" y="4.6" width="12.4" height="6.8" rx="3.4"/><circle cx="10.4" cy="8" r="2.2"/>'}
  ];
  var VIEWS=DOMAINS.map(function(d){ return {id:d.id,name:d.n}; });
  var current='overview';

