  function sv2SfrpLoad(t){
    if(t==='stat') return sv2SfrpStat();
    if(t==='conf'){
      shell('head -n1 '+SF_DIR+'args.txt 2>/dev/null; echo ---; cat '+SF_DIR+'frpc.ini 2>/dev/null')
        .then(function(o){
          var key=String(o).split('---')[0].trim(), ini=String(o).split('---').slice(1).join('---');
          fillSlot('sf-key',kv({'当前密钥':key?esc(key.slice(0,4)+'••••'+key.slice(-3)):badge(false,'未设置'),
            '文件':esc(SF_DIR+'args.txt')}));
          /* 空 ini 仅填编辑器最小模板，不写设备 */
          var ti=$('#sf-inita'); if(ti) ti.value=ini.trim()?ini:'[common]\nuser = your_token\nserver_addr = natfrp.com\nserver_port = 7000\n[tunnel]\ntype = tcp\nlocal_port = 80\nremote_port = 8080';
          var ki=$('#sf-keyin'); if(ki) ki.value=key;
        }).catch(failH('sf-key','sfrp'));
      return;
    }
    sv2LogInit('sfrp',SF_DIR+'frpc.log'); sv2LogPoll('sfrp');
    sv2LogInit('sfg',SF_DIR+'guard.log'); sv2LogPoll('sfg');
  }
  /* 断联守护：banner + 详情（数据来自 guard.sh st：前半 K=V，--- 之后是 health.state）。
     🔴 判据的三级证据要在界面上说清，否则用户看到 warn 会以为是误报：
        「本地服务」是 OpenList 自身，「端到端」才是隧道是否真的能通。 */
  /* 守护回传的 code 只有三档能直接当状态色，其余一律按 off 处理
     （设备侧桥脚本升级可能多给字段，不能让未知值漏进 is-XXX 类名）。
     v2.4.62：原是四层嵌套三元做恒等映射，加一档就要再套一层，改白名单。
     🔴 用数组 indexOf 而不是对象表：code 来自设备日志，对象表遇到 'constructor' / '__proto__'
        会命中原型链返回函数/对象，状态色就废了。 */
  var SF_GUARD_ST=['ok','warn','bad'];
  function sfHhmm(t){ return new Date(num(t)*1000).toLocaleTimeString('zh-CN',{hour12:false}); }
  function sv2SfGuardPaint(raw){
    var t=String(raw||''), gi=t.indexOf('---');
    var m=sv2Kv(gi>=0?t.slice(0,gi):t), h=sv2Kv(gi>=0?t.slice(gi+3):'');
    var run=!!m.G, code=h.code||'', ts=num(h.ts), iv=num(h.iv)||180;
    var stopped=(m.STOP==='1');
    var st=!run?'off':(SF_GUARD_ST.indexOf(code)>=0?code:'off');
    var title=run?(h.title||'等待首轮检测'):(stopped?'守护已停止（手动）':'守护未运行');
    var sub=run?(h.sub||('每 '+(iv/60)+' 分钟端到端探测一次'))
      :(stopped?'你手动停止了守护，断联后不会自动恢复；点「启动守护」重新开启'
        :'断联后不会自动恢复；点「启动守护」开启，每 '+Math.round(iv/60)+' 分钟探一次公网');
    patchSlot('sf-hb',svcHealthBanner(st,title,sub));
    var gpid=m.G?String(m.G).trim():'';
    var rows={
      '守护进程':run?badge(true,'运行中 · PID '+esc(gpid)):badge(false,'未运行'),
      '探测方式':'设备内 curl 打公网地址',
      '探测间隔':'每 '+(iv/60)+' 分钟',
      '自动重启':h.auto==='0'?'<span class="a2-badge is-off">已关闭</span>':badge(true,'开启'),
      '最近检测':ts?(sfHhmm(ts)+' · '+ago(ts*1000)):'<span class="a2-note">尚未检测</span>',
      '检测结论':run?esc(h.title||'--'):'--',
      '端到端':h.url?(esc(h.url)+' 返回 '+esc(h.pcode||'--')+(num(h.lat)>0?' · '+num(h.lat)+'ms':'')):'--',
      '本地服务':esc('返回 '+(h.lcode||'--')),
      '连续失败':num(h.fail)+' / '+num(h.need||2)+' 次触发重启',
      '累计重启':num(h.restart)+' 次'+(num(h.last)>0?' · 上次 '+sfHhmm(num(h.last)):''),
      '熔断保护':h.fuse==='1'?'<span class="a2-badge is-off">已熔断</span>':'未触发'
    };
    var dyn='';
    if(h.fuse==='1') dyn+=btn('解除熔断','sfguard','fuse-clear',
      '清除熔断标记并清零切换计数，守护将继续按策略自动恢复',true);
    dyn+=h.auto==='0'
      ? btn('开启自动重启','sfguard','auto-on')
      : btn('关闭自动重启','sfguard','auto-off','关闭后断联只报警、不再自动重启，确定？',true);
    patchSlot('sf-guard',kv(rows,'2')+'<div class="a2-btns is-tail">'+dyn+'</div>');
  }
  function sv2SfrpStat(){
    /* 先确保守护脚本就位（幂等），再一把把 frpc 状态 / 隧道 / 日志尾部 / 守护状态取回来 */
    return sfReady().then(function(){
      /* 相对路径启动时 -f 会漏检，统一用 -x frpc */
      return shell(psQ('frpc','-x')+'; '+
        'echo "INST=$([ -x '+SF_DIR+'frpc ] && echo 1 || echo 0)"; '+
        'echo "BOOT=$(grep -c "kano_sakurafrp" /sdcard/ufi_tools_boot.sh 2>/dev/null)"; '+
        'echo "MODE=$([ -s '+SF_DIR+'frpc.ini ] && echo 配置 || echo 密钥)"; '+
        'echo "LSZ=$(stat -c %s '+SF_DIR+'frpc.log 2>/dev/null)"; '+
        'echo "SA=$(grep -m1 server_addr '+SF_DIR+'frpc.ini 2>/dev/null | sed "s/.*= *//")"; echo ---; '+
        'cat '+SF_DIR+'tunnels.json 2>/dev/null; echo "===SFLOG==="; '+
        'grep -E "proxy starting|Connect to your tunnel|^ *- " '+SF_DIR+'frpc.log 2>/dev/null | tail -n 40; '+
        'echo "===SFG==="; sh '+SF_GUARD+' st 2>/dev/null');
    }).then(function(o){
        var parts=String(o).split('===SFLOG===');
        var tail=String(parts[1]||''), gp='';
        var mi=tail.indexOf('===SFG===');
        if(mi>=0){ gp=tail.slice(mi+9); tail=tail.slice(0,mi); }
        var head=parts[0]||'', m=sv2Kv(head.split('---')[0]), inst=(m.INST==='1')||!!m.P;
        /* 🔴 未安装一律不算运行中 */
        var run=!!m.P&&inst;
        SV2.stat.sfrp={pid:inst?(m.P||''):'',inst:inst}; sv2PaintSt();
        svcBtnState('sfrp',inst,run);
        patchSlot('sf-st',kv({
          '服务状态':run?badge(true,'运行中'):badge(false,inst?'已停止':'未安装'),
          'PID':m.P?esc(m.P):'--',
          '内存':m.R?bytes(num(m.R)*1024):'--',
          '运行时长':m.T?esc(m.T):'--',
          '开机自启':badge(num(m.BOOT)>0,'开'),
          '启动方式':esc(m.MODE||'--'),
          '日志':m.LSZ?bytes(num(m.LSZ)):'--'}));
        var tj=head.split('---').slice(1).join('---').trim();
        sv2SfLinks(tail, m.SA||'', tj);
        sv2SfTunnels(tj);
        sv2SfGuardPaint(gp);
      }).catch(failH('sf-st','sfrp'));
  }
  /* ---- 访问链接：日志里抓 frpc 打印的公网地址，tunnels.json + server_addr 兜底 ----
     日志格式（实测）：proxy starting: [名称, 类型] → Connect to your tunnel with >>host:port<<
     → 备线行「- China Telecom: dx.host:port」。解析保留每个隧道最后一次成功的地址。 */
  function sfCarrier(s){
    if(/telecom|电信/i.test(s)) return '电信';
    if(/unicom|联通/i.test(s)) return '联通';
    if(/mobile|移动/i.test(s)) return '移动';
    if(/broadnet|广电/i.test(s)) return '广电';
    return s;
  }
  function sv2SfLinks(logTail,saddr,tunRaw){
    var list=[],cur=null,last=null,seen={};
    function put(name,type,url){
      if(seen[name]!=null){
        last=list[seen[name]]; last.url=url; if(type) last.type=type;
        last.alts=[]; /* 重新拿到地址 ⇒ 旧块（含历史重启块）的备线全部作废 */
        return;
      }
      last={name:name||'隧道',type:String(type||'').toLowerCase(),url:url,alts:[]};
      seen[name]=list.length; list.push(last);
    }
    String(logTail||'').split(/\r?\n/).forEach(function(line){
      var m=/proxy starting: \[([^,\]]+),\s*([a-z0-9]+)\]/i.exec(line);
      if(m){ cur={name:m[1],type:m[2].toLowerCase()}; return; }
      m=/Connect to your tunnel with >>([^<]+)<</i.exec(line);
      if(m){ put(cur?cur.name:'隧道',cur?cur.type:'',m[1].trim()); return; }
      m=/^\s*-\s*([^:：]{2,24})[:：]\s*(\S+)\s*$/.exec(line);
      if(m&&last&&/telecom|unicom|mobile|broadnet|电信|联通|移动|广电/i.test(m[1])&&
        !last.alts.some(function(a){ return a.u===m[2]; }))
        last.alts.push({c:sfCarrier(m[1]),u:m[2].trim()});
    });
    var tuns=null; try{ tuns=JSON.parse(String(tunRaw||'[]')); }catch(e){ swallow(e,'scroll:root'); }
    if(Array.isArray(tuns)&&tuns.length){
      /* 日志里已下线的旧隧道不再展示；缓存里新增而日志未打出的，用 server_addr:remote 兜底 */
      list=list.filter(function(x){ return tuns.some(function(t){ return t.name===x.name; }); });
      tuns.forEach(function(t){
        var nm=t.name||('隧道'+t.id);
        if(seen[nm]!=null) return;
        if((t.type==='tcp'||t.type==='udp')&&t.remote&&saddr) put(nm,t.type,String(saddr)+':'+t.remote);
      });
    }
    /* 逐字段赋值：整体替换会把 sfReady 的 grdy/gp 缓存一起冲掉，每轮刷新都重新部署 */
    SV2.sfrp.links=list;
    sv2SfLinkPaint();
  }
  function sv2SfLinkPaint(){
    var L=(SV2.sfrp&&SV2.sfrp.links)||[],h='';
    L.forEach(function(x){
      if(!x.url) return;
      var url=String(x.url), isHttp=/^https?:\/\//i.test(url);
      var canOpen=x.type==='http'||x.type==='https'||isHttp||x.type==='tcp';
      h+='<div class="a2-lk">'+
        '<div class="a2-lk-h"><span class="a2-lk-n">'+esc(x.name)+'</span>'+
        (x.type?'<span class="a2-badge">'+esc(x.type.toUpperCase())+'</span>':'')+
        '<span class="a2-badge">已建立</span></div>'+
        '<div class="a2-lk-u">'+esc(url)+'</div>'+
        '<div class="a2-lk-b">'+btn('复制','sfcopy',url)+
        (canOpen?'<a class="a2-btn" href="'+esc(isHttp?url:('http://'+url))+'" target="_blank" rel="noopener">打开</a>':'')+
        '</div>';
      if(x.alts&&x.alts.length)
        h+='<div class="a2-lk-alt"><span class="a2-lk-lt">备线·点按复制</span>'+
          x.alts.map(function(a){
            return '<button type="button" class="a2-lk-chip" data-a="sfcopy" data-cmd="'+esc(a.u)+'">'+
              '<b>'+esc(a.c)+'</b> '+esc(a.u)+'</button>';
          }).join('')+'</div>';
      h+='</div>';
    });
    if(!h){
      patchSlot('sf-link','<div class="a2-note">'+
        ((SV2.stat.sfrp||{}).pid?'frpc 运行中，隧道尚未建立完成（或日志里还没有地址），稍后自动刷新。'
          :'frpc 未运行；启动并等隧道建立后，公网地址会出现在这里。')+'</div>');
      return;
    }
    patchSlot('sf-link',h);
  }
  function sv2SfTunnels(raw){
    var list=null;
    try{ list=JSON.parse(String(raw||'[]')); }catch(e){ swallow(e,'scroll:body'); }
    if(!list||!list.length){
      patchSlot('sf-tun','<div class="a2-note">暂无隧道缓存，点「拉取隧道列表」从官方接口同步。</div>'); return;
    }
    var links={}; ((SV2.sfrp||{}).links||[]).forEach(function(x){ if(x.url) links[x.name]=x.url; });
    /* 窄屏堆叠块代替横向表：名称/徽标一行，本地与公网两行，避免公网地址被裁剪 */
    patchSlot('sf-tun',list.map(function(t){
      var pub=links[t.name]||((t.remote||t.remote_port)?':'.concat(t.remote||t.remote_port):'--');
      var st=!t.online?'<span class="a2-badge is-off">离线</span>'
        :(t.status===2?'<span class="a2-badge is-off">封禁</span>':'<span class="a2-badge">在线</span>');
      return '<div class="a2-sftun" data-k="'+esc(String(t.id||t.name||''))+'">'+
        '<div class="a2-sftun-h"><b>'+esc(t.name||'')+'</b>'+
        (t.type?'<span class="a2-badge">'+esc(String(t.type).toUpperCase())+'</span>':'')+
        st+'<span class="a2-note">#'+esc(t.id||'')+'</span></div>'+
        '<div class="a2-kv is-dense">'+
        '<div class="a2-k"><span>本地</span><b class="a2-mono">'+esc((t.local_ip||'')+':'+(t.local_port||''))+'</b></div>'+
        '<div class="a2-k"><span>公网</span><b class="a2-mono">'+esc(pub)+'</b></div>'+
        '</div></div>';
    }).join(''));
  }
  /* ================= OpenList ================= */
